head.b:skin:
/*
-----------------------------------------------
Template Name  : Tungsten
Author         : NewBloggerThemes.com
Author URL     : http://btemplates.com/author/new-blogger-themes/
Theme URL      : http://btemplates.com/author/new-blogger-themes/tungsten-blogger-template/
Created Date   : Monday, June 9, 2014
License        : This template is free for both personal and commercial use, But to satisfy the 'attribution' clause of the license, you are required to keep the footer links intact which provides due credit to its authors.For more information about this license, please use this link :http://creativecommons.org/licenses/by/3.0/
----------------------------------------------- */
body#layout ul{list-style-type:none;list-style:none}
body#layout ul li{list-style-type:none;list-style:none}
body#layout #headerbwrap {height:auto;}
body#layout .rslides {display:none;}
/* Variable definitions
   ====================

*/

/* Use this with templates/template-twocol.html */

.section, .widget {
  margin:0;
  padding:0;
}

/* =Reset
-------------------------------------------------------------- */

html, body, div, span, applet, object, iframe,
h1, h2, h3, h4, h5, h6, p, blockquote, pre,
a, abbr, acronym, address, big, cite, code,
del, dfn, em, font, ins, kbd, q, s, samp,
small, strike, strong, sub, sup, tt, var,
dl, dt, dd, ol, ul, li,
fieldset, form, label, legend,
table, caption, tbody, tfoot, thead, tr, th, td {
	border: 0;
	font-family: inherit;
	font-size: 100%;
	font-style: inherit;
	font-weight: inherit;
	margin: 0;
	outline: 0;
	padding: 0;
	vertical-align: baseline;
}
html {
	font-size: 62.5%; /* Corrects text resizing oddly in IE6/7 when body font-size is set using em units http://clagnut.com/blog/348/#c790 */
	overflow-y: scroll; /* Keeps page centered in all browsers regardless of content height */
	-webkit-text-size-adjust: 100%; /* Prevents iOS text size adjust after orientation change, without disabling user zoom */
	-ms-text-size-adjust:     100%; /* www.456bereastreet.com/archive/201012/controlling_text_size_in_safari_for_ios_without_disabling_user_zoom/ */
}
*,
*:before,
*:after { /* apply a natural box layout model to all elements; see http://www.paulirish.com/2012/box-sizing-border-box-ftw/ */
	-webkit-box-sizing: border-box; /* Not needed for modern webkit but still used by Blackberry Browser 7.0; see http://caniuse.com/#search=box-sizing */
	-moz-box-sizing:    border-box; /* Still needed for Firefox 28; see http://caniuse.com/#search=box-sizing */
	box-sizing:         border-box;
}
body {
	background: url(https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEiQjxLwm0T5wQSXx-muj04bhKww0H8JtyYmFuRCk0foiMuLsmMw3Ez7a0FzvFKA0QGI_zVEstAdNAhzIYA66UJIzrREiYPG6L4F_5A3EolwIiuNrSGChqGWhf7K-lLW4Q1Ba_5OGCjy3qE/s0/body-bg.png) #161616;
	-ms-word-wrap: break-word;
	word-wrap: break-word;
}
article,
aside,
details,
figcaption,
figure,
footer,
header,
main,
nav,
section {
	display: block;
}
ol, ul {
	list-style: none;
}
table { /* tables still need 'cellspacing="0"' in the markup */
	border-collapse: separate;
	border-spacing: 0;
}
caption, th, td {
	font-weight: normal;
	text-align: left;
}
blockquote:before, blockquote:after,
q:before, q:after {
	content: "";
}
blockquote, q {
	quotes: "" "";
}
a:focus {
	outline: thin dotted;
}
a:hover,
a:active {
	outline: 0;
}
a img {
	border: 0;
}

/* =Global
----------------------------------------------- */

body,
button,
input,
select,
textarea {
	color: #404040;
	font-family: 'Merriweather', 'Open Sans', sans-serif;
	font-size: 14px;
	font-size: 1.4rem;
	font-weight: 300;
	line-height: 1.6;
}

a, a:visited {
	color: #BC2605;
}
a:hover,
a:focus,
a:active {
	color: #DD4726;
}

/* Headings */
h1, h2, h3, h4, h5, h6 {
	clear: both;
	margin-bottom: 10px;
}

h1 {
    font-size: 2.6em;
}
h2 {
    font-size: 2.2em;
}
h3 {
    font-size: 1.8em;
}
h4 {
    font-size: 1.6em;
}
h5 {
    font-size: 1.4em;
}
h6 {
    font-size: 1.2em;
}

hr {
	background-color: #ccc;
	border: 0;
	height: 1px;
	margin-bottom: 1.5em;
}

/* Text elements */
p {
	margin-bottom: 1.5em;
}
ul, ol {
	margin: 0 0 1.5em 3em;
}
ul {
	list-style: disc;
}
ol {
	list-style: decimal;
}
li > ul,
li > ol {
	margin-bottom: 0;
	margin-left: 1.5em;
}
dt {
	font-weight: bold;
}
dd {
	margin: 0 1.5em 1.5em;
}
b, strong {
	font-weight: bold;
}
dfn, cite, em, i {
	font-style: italic;
}
blockquote {
    background: none repeat scroll 0 0 #F2F2F2;
    margin: 1.5em;
    padding: 20px;
}
blockquote p{
	margin-bottom: 0;
}
address {
	margin: 0 0 1.5em;
}
pre {
	background: #eee;
	font-family: "Courier 10 Pitch", Courier, monospace;
	font-size: 14px;
	font-size: 1.4rem;
	line-height: 1.6;
	margin-bottom: 1.6em;
	max-width: 100%;
	overflow: auto;
	padding: 1.6em;
}
code, kbd, tt, var {
	font: 14px Monaco, Consolas, "Andale Mono", "DejaVu Sans Mono", monospace;
}
abbr, acronym {
	border-bottom: 1px dotted #666;
	cursor: help;
}
mark, ins {
	background: #fff9c0;
	text-decoration: none;
}
sup,
sub {
	font-size: 75%;
	height: 0;
	line-height: 0;
	position: relative;
	vertical-align: baseline;
}
sup {
	bottom: 1ex;
}
sub {
	top: .5ex;
}
small {
	font-size: 75%;
}
big {
	font-size: 125%;
}
figure {
	margin: 0;
}
table {
	margin: 0 0 1.5em;
	width: 100%;
}
th {
	font-weight: bold;
	background:#DD4726;
	color:#FFF;
	padding:10px;
	border-bottom: 1px solid #EEEEEE;
}
td{
	padding:10px;
}
tr.even{
	background: #f1f1f1;
}
img {
	height: auto; /* Make sure images are scaled correctly. */
	max-width: 100%; /* Adhere to container width. */
}
button,
input,
select,
textarea {
	font-size: 100%; /* Corrects font size not being inherited in all browsers */
	margin: 0; /* Addresses margins set differently in IE6/7, F3/4, S5, Chrome */
	vertical-align: baseline; /* Improves appearance and consistency in all browsers */
	*vertical-align: middle; /* Improves appearance and consistency in all browsers */
}
button,
input[type="button"],
input[type="reset"],
input[type="submit"] {
	border: 1px solid #ccc;
	border-color: #ccc #ccc #bbb #ccc;
	border-radius: 3px;
	background: #e6e6e6;
	box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.5), inset 0 15px 17px rgba(255, 255, 255, 0.5), inset 0 -5px 12px rgba(0, 0, 0, 0.05);
	color: rgba(0, 0, 0, .8);
	cursor: pointer; /* Improves usability and consistency of cursor style between image-type 'input' and others */
	-webkit-appearance: button; /* Corrects inability to style clickable 'input' types in iOS */
	font-size: 12px;
	font-size: 1.2rem;
	line-height: 1;
	padding: .6em 1em .4em;
	text-shadow: 0 1px 0 rgba(255, 255, 255, 0.8);
}
button:hover,
input[type="button"]:hover,
input[type="reset"]:hover,
input[type="submit"]:hover {
	border-color: #ccc #bbb #aaa #bbb;
	box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.8), inset 0 15px 17px rgba(255, 255, 255, 0.8), inset 0 -5px 12px rgba(0, 0, 0, 0.02);
}
button:focus,
input[type="button"]:focus,
input[type="reset"]:focus,
input[type="submit"]:focus,
button:active,
input[type="button"]:active,
input[type="reset"]:active,
input[type="submit"]:active {
	border-color: #aaa #bbb #bbb #bbb;
	box-shadow: inset 0 -1px 0 rgba(255, 255, 255, 0.5), inset 0 2px 5px rgba(0, 0, 0, 0.15);
}
input[type="checkbox"],
input[type="radio"] {
	padding: 0; /* Addresses excess padding in IE8/9 */
}
input[type="search"] {
	-webkit-appearance: textfield; /* Addresses appearance set to searchfield in S5, Chrome */
	-webkit-box-sizing: content-box; /* Addresses box sizing set to border-box in S5, Chrome (include -moz to future-proof) */
	-moz-box-sizing:    content-box;
	box-sizing:         content-box;
}
input[type="search"]::-webkit-search-decoration { /* Corrects inner padding displayed oddly in S5, Chrome on OSX */
	-webkit-appearance: none;
}
button::-moz-focus-inner,
input::-moz-focus-inner { /* Corrects inner padding and border displayed oddly in FF3/4 www.sitepen.com/blog/2008/05/14/the-devils-in-the-details-fixing-dojos-toolbar-buttons/ */
	border: 0;
	padding: 0;
}
input[type="text"],
input[type="email"],
input[type="url"],
input[type="password"],
input[type="search"],
textarea {
	color: #666;
	border: 1px solid #ccc;
	border-radius: 3px;
}
input[type="text"]:focus,
input[type="email"]:focus,
input[type="url"]:focus,
input[type="password"]:focus,
input[type="search"]:focus,
textarea:focus {
	color: #111;
}
input[type="text"],
input[type="email"],
input[type="url"],
input[type="password"],
input[type="search"] {
	padding: 3px;
}
textarea {
	overflow: auto; /* Removes default vertical scrollbar in IE6/7/8/9 */
	padding-left: 3px;
	vertical-align: top; /* Improves readability and alignment in all browsers */
	width: 98%;
}

/* Alignment */
.alignleft {
	display: inline;
	float: left;
	margin-right: 1.5em;
}
.alignright {
	display: inline;
	float: right;
	margin-left: 1.5em;
}
.aligncenter {
	clear: both;
	display: block;
	margin: 0 auto;
}

/* Text meant only for screen readers */
.screen-reader-text {
	clip: rect(1px, 1px, 1px, 1px);
	position: absolute !important;
}

.screen-reader-text:hover,
.screen-reader-text:active,
.screen-reader-text:focus {
	background-color: #f1f1f1;
	border-radius: 3px;
	box-shadow: 0 0 2px 2px rgba(0, 0, 0, 0.6);
	clip: auto !important;
	color: #21759b;
	display: block;
	font-size: 14px;
	font-weight: bold;
	height: auto;
	left: 5px;
	line-height: normal;
	padding: 15px 23px 14px;
	text-decoration: none;
	top: 5px;
	width: auto;
	z-index: 100000; /* Above WP toolbar */
}

/* Clearing */
.clear:before,
.clear:after,
.entry-content:before,
.entry-content:after,
.comment-content:before,
.comment-content:after,
.site-headernbt:before,
.site-headernbt:after,
.site-contentnbt:before,
.site-contentnbt:after,
.site-footernbt:before,
.site-footernbt:after {
	content: '';
	display: table;
}

.clear:after,
.entry-content:after,
.comment-content:after,
.site-headernbt:after,
.site-contentnbt:after,
.site-footernbt:after {
	clear: both;
}

/* =Grid
----------------------------------------------- */

@media only screen and (min-width:768px){
.onecol{width:5.801104972%;}
.twocol{width:14.364640883%;}
.threecol{width:22.928176794%;}
.fourcol{width:31.491712705%;}
.fivecol{width:40.055248616%;}
.sixcol{width:48.618784527%;}
.sevencol{width:57.182320438000005%;}
.eightcol{width:65.74585634900001%;}
.ninecol{width:74.30939226%;}
.tencol{width:82.87292817100001%;}
.elevencol{width:91.436464082%;}
.twelvecol{width:99.999999993%;}
.onecol,.twocol,.threecol,.fourcol,.fivecol,.sixcol,.sevencol,.eightcol,.ninecol,.tencol,.elevencol,.twelvecol{position:relative;float:left;margin-left:2.762430939%;} 
.first{margin-left:0;}
.last{float:right;}
}
.clearfixnbt{zoom:1;}.clearfixnbt:before,.clearfixnbt:after{content:"";display:table;}
.clearfixnbt:after{clear:both;}

/* =Header
----------------------------------------------- */
.site-brandingnbt {
    padding: 20px 0 25px;
}
.site-brandingnbt img#logo {
    max-width: 300px;
}

h1.site-title {
    font-size: 40px;
    font-weight: bold;
    margin-bottom: 0;
    letter-spacing: -1px;
}

h1.site-title > a,
h1.site-title > a:hover,
h1.site-title > a:focus,
h1.site-title > a:active,
h1.site-title > a:visited {
    color: #fff;
    text-shadow:2px 2px #000;
    text-decoration: none;
}

h2.site-description {
    color: #ddd;
    text-shadow:2px 2px #000;
    font-size: 16px;
    margin-bottom: 0;
}



@media screen and (min-width: 700px) {
	.content-areanbt {
		float: left;
		margin: 0 -30% 0 0;
		width: 100%;
	}
	.site-mainnbt {
		margin: 0 30% 0 0;
	}
	.site-contentnbt .widget-areanbt {
		float: right;
		overflow: hidden;
		width: 30%;
	}
	.site-footernbt {
		clear: both;
		width: 100%;
	}


	.sidebar-content-layout .content-areanbt {
		float: right;
		margin: 0 0 0 -25%;
		width: 100%;
	}
	.sidebar-content-layout .site-mainnbt {
		margin: 0 0 0 25%;
	}
	.sidebar-content-layout .site-contentnbt .widget-areanbt {
		float: left;
		overflow: hidden;
		width: 25%;
	}
	.sidebar-content-layout .site-footernbt {
		clear: both;
		width: 100%;
	}

	.social_wrapnbt{
		display: block;
	}
}

/* =Color Schemes
----------------------------------------------- */

.main-navigationnbt,
.site-footernbt {
	background: url(https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEghHxtBLaw2vRnrPplugNm8kTuaOPyhDcvHx8qbz0hVuy3aNxGwSCPi6y8slf4wpaCGlvUANZvSuRKvEQf0Fspw5kSB_cjBLwwV4tCns0hHPfJf41e5hK1-hIvuv5_8R4-W3KDWYYtsOgw/s0/bg.png) #DD4726;
}
.main-navigationnbt ul ul a {
	border-bottom: 1px solid #DA4423;
}
.main-navigationnbt {
	box-shadow: 0 -2px 2px #C42E0D inset;
}
.main-navigationnbt .current_page_item a,
.main-navigationnbt .current-menu-item a{
	box-shadow: 1px 0 #C42E0D;
}
.main-navigationnbt .current_page_item a,
.main-navigationnbt ul li:hover a,
.main-navigationnbt .current-menu-item a{
	background: #F86241;
}
#contentnbt {
    border-top: 6px solid #F86241;
}
.main-navigationnbt a,
.site-footernbt {
    text-shadow: 1px 1px #CD3717;
}
h1.entry-title > a,
h1.entry-title > a:visited {
    color: #1B1B1B;
    text-decoration: none;
}
h1.entry-title > a:hover {
	color: #DD4726;
}
.rslides .caption {
    background: #DD4726;
    z-index: 9999;
}

/*----------------------------------*/
.blue-skin a,
.blue-skin a:visited {
	color: #4862A3;
}
.blue-skin a:hover,
.blue-skin a:focus,
.blue-skin a:active {
	color: #5E78B9;
}
.blue-skin h1.entry-title > a:hover {
	color: #4862A3;
}
.blue-skin .main-navigationnbt,
.blue-skin .site-footernbt {
	background: url(https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEghHxtBLaw2vRnrPplugNm8kTuaOPyhDcvHx8qbz0hVuy3aNxGwSCPi6y8slf4wpaCGlvUANZvSuRKvEQf0Fspw5kSB_cjBLwwV4tCns0hHPfJf41e5hK1-hIvuv5_8R4-W3KDWYYtsOgw/s0/bg.png) #4862A3;
}
.blue-skin .main-navigationnbt ul ul a {
	border-bottom: 1px solid #3A5495;
}
.blue-skin .main-navigationnbt {
	box-shadow: 0 -2px 2px #233D7E inset;
}
.blue-skin .main-navigationnbt .current_page_item a,
.blue-skin .main-navigationnbt .current-menu-item a{
	box-shadow: 1px 0 #233D7E;
}
.blue-skin .main-navigationnbt .current_page_item a,
.blue-skin .main-navigationnbt ul li:hover a,
.blue-skin .main-navigationnbt .current-menu-item a{
	background: #5D77B8;
}
.blue-skin #contentnbt {
    border-top: 6px solid #5D77B8;
}
.blue-skin .main-navigationnbt a,
.blue-skin .site-footernbt {
    text-shadow: 1px 1px #233D7E;
}
.blue-skin .rslides .caption {
    background: #4862A3;
}
.blue-skin th {
	background: #4862A3;
}

/* =Menu
----------------------------------------------- */

.main-navigationnbt {
	clear: both;
	display: block;
	float: left;
	width: 100%;
}
.main-navigationnbt ul {
	list-style: none;
	margin: 0;
	padding-left: 0;
}
.main-navigationnbt li {
	float: left;
	position: relative;
}

.main-navigationnbt a,
.main-navigationnbt a:visited, 
.main-navigationnbt a:hover,
.main-navigationnbt a:focus,
.main-navigationnbt a:active{
	display: block;
	text-decoration: none;
    color: #FFFFFF;
    padding: 10px;
}
.main-navigationnbt a,
.main-navigationnbt ul ul,
.main-navigationnbt ul ul ul {
	transition: all 0.1s ease-in-out 0s;
}
.main-navigationnbt > ul li:first-child a {
    margin-left: 0;
}

.main-navigationnbt ul ul {
	box-shadow: 0 3px 3px rgba(0, 0, 0, 0.5);
	display: none;
	float: left;
	left: 0;
	position: absolute;
	top: 100%;
	z-index: 99999;
}
.main-navigationnbt ul ul ul {
	left: 100%;
	top: 0;
}
.main-navigationnbt ul ul a {
    width: 200px;
    box-shadow: none !important;
}
.main-navigationnbt li:hover > a {
}
.main-navigationnbt ul ul :hover > a {
}
.main-navigationnbt ul ul a:hover {
}
.main-navigationnbt ul li:hover > ul {
	display: block;
}
.main-navigationnbt .current_page_item a,
.main-navigationnbt .current-menu-item a {
}

/* Small menu */
.menu-togglenbt {
	cursor: pointer;
	display: none;
    color: #FFFFFF;
    font-size: 25px;
    font-weight: 300;
    text-align: center;
    text-decoration: underline;
}

@media screen and (max-width: 600px) {
	.menu-togglenbt,
	.main-navigationnbt.toggled .nav-menu {
		display: block;
	}

	.main-navigationnbt ul {
		display: none;
	}
}

/* =Content
----------------------------------------------- */

#pagenbt {
    margin: 0 auto 20px;
    max-width: 1200px;
    padding: 0 40px;
}
#contentnbt {
    background: #FFFFFF;
    display: block;
}
.clear{
	clear:both;
}
#mainnbt{
    padding: 20px;
    font-size: 15px;
    font-weight: 400;
}
.entry-title {
    font-size: 25px;
    font-weight: bold;
}
.entry-metanbt,
.entry-metanbt a,
.entry-metanbt a:hover,
.entry-metanbt a:focus,
.entry-metanbt a:visited,
.entry-metanbt a:active {
    color: #9C9C9C;
    font-size: 14px;
	text-decoration: none;
}
footer.entry-metanbt {
  margin: 0;
}
.readmorenbt {
  text-decoration: none;
}
.entry-thumbnail,
.entry-text{
	display: block;
}
.entry-thumbnail{
	width:23%;
	float:left;
	text-align: center;
}
.entry-text{
	width:75%;
	float:right;
}
.entry-summary {
    margin: 0.8em 0 0;
}
.entry-summary > p {
    margin-bottom: 0;
}
.hentry {
    border-bottom: 1px solid #E7E7E7;
    margin: 0 0 20px;
    padding-bottom: 20px;
}
.byline,
.updated {
}
.single .byline,
.group-blog .byline {
}
.page-content,
.entry-content {
	margin: 1em 0 1em;
}

/* =Asides
----------------------------------------------- */

.blog .format-aside .entry-title,
.archive .format-aside .entry-title {
}

/* =Footer
----------------------------------------------- */

.site-infonbt {
    color: #FFFFFF;
    padding: 20px 40px;
	text-align: center;
}

.site-footernbt a,
.site-footernbt a:active,
.site-footernbt a:focus,
.site-footernbt a:hover,
.site-footernbt a:visited{
	color: #FFFFFF;
}

.creditsnbt {
    float: none;
}
.copyright-textnbt{
	float: none;
}

/* Make sure embeds and iframes fit their containers */
embed,
iframe,
object {
	max-width: 100%;
}

/* =Widgets
----------------------------------------------- */

.site-contentnbt .widget-areanbt {
	padding-top: 20px;
    background: #F6F6F6;
    -webkit-border-radius: 0 0 0 30px;
    -moz-border-radius: 0 0 0 30px;
    border-radius: 0 0 0 30px;
    margin-bottom: 20px;
    color: #888888;
}

.sidebar-content-layout .site-contentnbt .widget-areanbt {
	border-radius: 0 0 30px 0;
}

.widget-areanbt .widget-title{
	font-size: 20px;
	margin-bottom: 12px;
	color: #404040;
}

.widget-areanbt .widget h2{
	font-size: 20px;
	margin-bottom: 12px;
	color: #404040;
	font-weight: bold;
}

.widget-areanbt .widget h3{
	font-size: 20px;
	margin-bottom: 12px;
	color: #404040;
}

.widget-areanbt ul{
	margin: 0;
	list-style: none;
	list-style-type: none;
}

.widget-areanbt a,
.widget-areanbt a:hover,
.widget-areanbt a:active,
.widget-areanbt a:focus,
.widget-areanbt a:visited {
    border-bottom: 0px dotted;
    color: #888888;
    text-decoration: none;
}

.widget-areanbt .widget {
	border-bottom: 1px solid #DADADA;
    box-shadow: 0 1px #FFFFFF;
    margin: 0 15px 15px;
    padding-bottom: 15px;
}

.widget-areanbt .widget ul li:last-child {
    margin-bottom:0;
}

/* Make sure select elements fit in widgets */
.widget select {
	max-width: 100%;
}

/* Search widget */
.widget_search .search-submit {
	display: none;
}

.widget-areanbt li {
    margin-bottom: 8px;
}

/* =rSlides
----------------------------------------------------------*/

.rslides {
  position: relative;
  list-style: none;
  overflow: hidden;
  width: 100%;
  padding: 0;
  margin: 0;
  }

.rslides li {
  -webkit-backface-visibility: hidden;
  position: absolute;
  display: none;
  width: 100%;
  left: 0;
  top: 0;
  }

.rslides li:first-child {
  position: relative;
  display: block;
  float: left;
  }

.rslides img {
  display: block;
  height: auto;
  float: left;
  width: 100%;
  border: 0;
  }

.rslides .caption {
    bottom: 0;
    color: #FFFFFF;
    padding: 3px 20px;
    position: absolute;
}

h2.date-header {
  margin: 10px 0px;
  display: none;
}

.main .widget {
  margin: 0 0 5px;
  padding: 0 0 2px;
}

.main .Blog {
  border-bottom-width: 0;
}

#header .description {
  color:#ffffff;
  font-size:14px;
  text-shadow:0px 1px 0px #000000;
}

/* Comments----------------------------------------------- */
#comments {
	padding:10px;
	margin-bottom:20px;
}

#comments h4 {
    font-size:22px;
    margin-bottom:10px;
}

.deleted-comment {
  font-style: italic;
  color: gray;
}

#blog-pager-newer-link {
  float: left;
}

#blog-pager-older-link {
  float: right;
}

#blog-pager {
  text-align: center;
  padding:5px;
  margin: 1em 0;
}

.feed-links {
  clear: both;
}

.comment-form {
}

#navbar-iframe {
  height: 0;
  visibility: hidden;
  display: none;
}

.separator a[style="margin-left: 1em; margin-right: 1em;"] {margin-left: auto!important;margin-right: auto!important;}

.PopularPosts .widget-content ul li {
  padding:6px 0px;
}

.reaction-buttons table{
  border:none;
  margin-bottom:5px;
}

.reaction-buttons table, .reaction-buttons td{
  border:none !important;
}

.PopularPosts .item-title {
  font-weight: bold;
  padding-bottom: 0.2em;
}

.pbtthumbimg {
  float:left;
  margin:0px 10px 5px 0px;
  padding:0px;
  border:0px solid #eee;
  background:#fff;
  width:200px;
  height:auto;
}
.dropbtn {
  background-color: inherit;
  font-family: inherit;
}

.dropdown-content {
  display: none;
  position: absolute;
  background-color: #dd4726;
  min-width: 160px;
  box-shadow: 0px 8px 16px 0px rgba(0,0,0,0.2);
  z-index: 3;
}

.dropdown-content a {
  float: none;
  padding: 12px 16px;
  text-decoration: none;
  display: block;
  text-align: left;
  background-color: inherit;
}

.dropdown-content a:hover {
  background-color: inherit;
}

.dropdown:hover .dropdown-content {
  display: block;
}

.feed-links {display: none;}

#pagenbt {
  margin: 0 auto;
  max-width: none !important;
  width: 100% !important;
  padding: 0 !important;
}
body {
  margin: 0;
  padding: 0;
  background-color: #161616;
}
#contentnbt {
  width: 100% !important;
  margin: 0 auto;
}
@media screen and (max-width: 600px) {
  body, html {
    padding: 0;
    margin: 0;
  }
  #pagenbt, #contentnbt {
    padding: 0 !important;
    margin: 0 !important;
    width: 100% !important;
  }
}


.site-title {
  text-align: center !important;
}

/* Versione 4 - Riduzione margini header */
.site-brandingnbt {
  padding: 5px 0 5px !important;
}

h1.site-title {
  margin-top: 5px !important;
  margin-bottom: 5px !important;
}

h2.site-description {
  margin-top: 2px !important;
  margin-bottom: 4px !important;
}

#international-link {
  margin-top: 2px !important;
  margin-bottom: 4px !important;
  display: block !important;
}

